head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.v_SaveKind = ""; // 신규,수정 구분
scwin.vBzProcsNo = ""; // 업무처리번호
scwin.vIsuCd = ""; // 발행기관코드
scwin.vDisclsYn = ""; // 공시여부
scwin.vListBzTpCd = "790"; // 상장업무구분코드 (삭제시 필요) - 로그처리방지용
// 화면ID

// var vIsurCd  = "";                  // 상장인코드
// var vIsurNm = "";                    // 상장인명

// Transaction 처리코드
scwin.TR_JOB;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name canUploadFile
 * @description 2017-02-13 KBoY FileSizeLimit 30MB
 * @returns {void}
 * @hidden N
 */
scwin.canUploadFile = function() {
    const maxFileSize = 1024 * 1024 * 30; // 30MB
    const mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name filedown
 * @description 파일 다운로드 (gubun = 311) (Params : bzProcsNo:업무처리번호 , attachFileNo: 번호)
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} attachSeq attachSeq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(bzProcsNo, attachSeq) {
    location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF70030_N3.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&ATTACH_SEQ=" + attachSeq + "&gubun=311";
};

/**
 * @method
 * @name fileSync
 * @description 첨부파일 리스트 불러오기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileSync = async function() {
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_fileList",
        action : "/digital/DigitalListinvstg.do",
        ref : "",
        target : "dts_fileList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name checkForm
 * @description Form Validation Check
 * @param {*} kind kind
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function(kind) {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (cmb_DIGITAL_SECU_EXP_YN.getValue() === "") {
        await $c.win.alert("[만기유무]를 입력하세요.");
        cmb_DIGITAL_SECU_EXP_YN.focus();
        return false;
    }
    if (cmb_DIGITAL_SECU_EXP_YN.getValue() === "Y") {
        if (txb_EXP_DD.getValue() === "") {
            await $c.win.alert("[만기일]을 입력하세요.");
            txb_EXP_DD.focus();
            return false;
        }
        if (txb_LSTTRD_DD.getValue() === "") {
            await $c.win.alert("[최종거래일]을 입력하세요.");
            txb_LSTTRD_DD.focus();
            return false;
        }
    }
    if (edt_CHG_LIST_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }
    if (vCurDate >= edt_CHG_LIST_DD.getValue()) {
        await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }
    if (!await scwin.compDate()) return false;
    return true;
};

/**
 * @method
 * @name dupCheck
 * @description 종목 중복날짜 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dupCheck = async function() {
    const chgDd = edt_CHG_LIST_DD.getValue();
    let isNotDup = true;
    dts_DupChk.removeAll();
    const sbmOptions = {
        id : "sbm_dts_DupChk",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_DupChk=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_DupChk.getRowCount() > 0) {
        // 같은 건이 아니라면
        if (scwin.vBzProcsNo !== dts_DupChk.getCellData(1, "BZ_PROCS_NO")) {
            isNotDup = false;
            await $c.win.alert("동일한 날짜에 변경상장 지정된 종목이 존재합니다.");
        }
    }
    return isNotDup;
};

/**
 * @method
 * @name selectIsur
 * @description 만기변경 내역 신규 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectIsur = async function() {
    url += "&SCREN_ID=" + "ULDSTF70030_N3.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_ISU_CD=" + scwin.vIsuCd;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/digital/DigitalListinvstg.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // vIsurCd= dts_Isu.NameValue(1,"ISUR_CD");
    // vIsurNm = dts_Isu.NameValue(1,"ISUR_NM");

};

/**
 * @method
 * @name selectIsurDetail
 * @description 만기변경 내역 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectIsurDetail = async function() {
    url += "&SCREN_ID=" + "ULDSTF70030_N3.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&SRCH_ISU_CD=" + scwin.vIsuCd;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/digital/DigitalListinvstg.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // vIsurCd= dts_Isu.NameValue(1,"ISUR_CD");
    // vIsurNm = dts_Isu.NameValue(1,"ISUR_NM");

};

/**
 * @method
 * @name saveExpIsurNew
 * @description 변경상장 > 만기변경 > 신규저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveExpIsurNew = async function() {
    // if (fn_CheckForm(v_SaveKind) == false)
    // return;

    scwin.TR_JOB = 'I';
    if (await scwin.checkForm(scwin.v_SaveKind) && await scwin.dupCheck()) {
        // Transaction 처리전 안내문구
        if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
        // 저장 처리
        let vScrenId = "SCREN_ID=" + "ULDSTF70030_N3.xml";
        let vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        let vSrvMethod = "&method=insertExpChange";
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo); // 업무처리번호 새로 지정

        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : TR_JOB_INSERT,
        //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
        //     BZ_PROCS_NO : scwin.vBzProcsNo,
        //     ISU_CD : scwin.vIsuCd,
        //     ISUR_CD : dts_Isu.getCellData(1, "ISUR_CD"),
        //     ACPT_NO : js_emp_no,
        //     LD_MKT_TP_CD : "1",
        //     TRANSTR_EMP_NO : js_emp_no
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/digital/DigitalListinvstg.do",
            ref : "dts_Isu,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name saveExpIsurUpdate
 * @description 만기변경 > 상세보기  > 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveExpIsurUpdate = async function() {
    scwin.TR_JOB = 'U';

    // if (fn_CheckForm(TR_JOB) == false)
    //    return;

    if (($c.cp.isModified(dts_Isu) === false) && ($c.cp.isModified(dts_fileList) === false)) {
        await $c.win.alert("수정내역이 존재하지 않습니다.");
        return;
    }
    if (await scwin.checkForm(scwin.v_SaveKind) && await scwin.dupCheck()) {
        // Transaction 처리전 안내문구
        if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
        let vScrenId = "SCREN_ID=" + "ULDSTF70030_N3.xml";
        let vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        let vSrvMethod = "&method=updateExpChange";
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : TR_JOB_UPDATE,
        //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
        //     BZ_PROCS_NO : scwin.vBzProcsNo,
        //     ISU_CD : scwin.vIsuCd,
        //     ISUR_CD : dts_Isu.getCellData(1, "ISUR_CD"),
        //     ACPT_NO : js_emp_no,
        //     LD_MKT_TP_CD : "1",
        //     TRANSTR_EMP_NO : js_emp_no
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/digital/DigitalListinvstg.do",
            ref : "dts_Isu,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name saveExpIsurDelete
 * @description 변경상장 > 만기변경 > 삭제
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveExpIsurDelete = async function() {
    if (scwin.vBzProcsNo === "") {
        await $c.win.alert("삭제 정보(업무처리번호)가 없습니다.");
        return;
    }
    // 공시 체크
    if (!$c.lcd.fn_check_delete_discls(dts_BzProcsNo, scwin.vBzProcsNo)) return;
    scwin.TR_JOB = 'D';

    // Transaction 처리전 안내문구
    if (!$c.lcd.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    let vScrenId = "SCREN_ID=" + "ULDSTF70030_N3.xml";
    let vScrenTpId = "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    let vSrvMethod = "&method=deleteExpChange";

    // 상장업무구분코드 있는 경우에만 삭제 처리 함
    if (scwin.vListBzTpCd !== "") {
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : TR_JOB_DELETE,
        //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
        //     BZ_PROCS_NO : scwin.vBzProcsNo,
        //     ISU_CD : scwin.vIsuCd,
        //     ISUR_CD : dts_Isu.getCellData(1, "ISUR_CD"),
        //     ACPT_NO : js_emp_no,
        //     LD_MKT_TP_CD : "1",
        //     TRANSTR_EMP_NO : js_emp_no
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/digital/DigitalListinvstg.do",
            ref : "dts_Isu",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name checkModifyDts
 * @description 안내문작성 시, 수정사항 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkModifyDts = async function() {
    let rtn = false;
    if ($c.cp.isModified(dts_Isu) === false) {
        rtn = true;
    } else {
        await $c.win.alert("변경된 내용이 있습니다. [수정] 후 진행하세요.");
        rtn = false;
    }
    return rtn;
};

/**********************************************
 * 함수명 : fn_dscl()
 * 설명    : 수량변경 > 발행 및 상장내역 > 안내문 작성
 ***********************************************/
scwin.getPar, scwin.setPar;

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    const cCtnt = "";
    if (await scwin.checkModifyDts() === false) {
        return;
    }
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2) {
        arr[0] = "69565C";
        arr[1] = scwin.vBzProcsNo;
        arr[2] = dts_Isu.getCellData(1, "ISUR_CD");
        arr[3] = '1';
        // arr[4] = fn_getEtcChgDisclsCtnt(); //ctnt
        arr[5] = txb_ISU_NM.getValue(); // add  title

        const sfeDate = scwin.dateForm(txb_BF_EXP_DD.getValue());
        const seDate = scwin.dateForm(txb_EXP_DD.getValue());
        const sDate = scwin.dateForm(edt_CHG_LIST_DD.getValue());
        $c.stf.copyDataSet(dts_Isu, param_dts_isu);
        $c.stf.copyDataSet(dts_Isu, param_dts_mst);

        // 파라미터 ds 만 값 변경
        param_dts_isu.setCellData(param_dts_isu.getFocusedRowIndex(), "BF_EXP_DD", sfeDate); // 이전만기일
        param_dts_isu.setCellData(param_dts_isu.getFocusedRowIndex(), "EXP_DD", seDate); // 만기일
        param_dts_mst.setCellData(param_dts_isu.getFocusedRowIndex(), "BF_EXP_DD", sfeDate);
        param_dts_mst.setCellData(param_dts_isu.getFocusedRowIndex(), "EXP_DD", seDate);
        param_dts_isu.setCellData(param_dts_isu.getFocusedRowIndex(), "CHG_LIST_DD", sDate); // 변경상장일
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "CHG_LIST_DD", sDate);
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 750;
    const hgt = 820;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "변경상장 만기변경 안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;

    // 안내문팝업 후 '닫기'나 '안내문전송' 후에 Popup Close 및 Parent Refresh 함
    $c.frame.path("../").fn_list_exp_chglist_sync();
};

/**
 * @method
 * @name getEtcChgDisclsCtnt
 * @description 안내문작성 서식 (수량변경)
 * @returns {void}
 * @hidden N
 */
scwin.getEtcChgDisclsCtnt = function() {
    let vCtnt = "";
    vCtnt = "[공시제목] 신종증권 변경상장";
    vCtnt += "\r\n\r\n";
    vCtnt += "[본문내용]";
    vCtnt += "\r\n\r\n";
    vCtnt += "◎ " + txb_ISU_NM.getValue() + " 변경상장(만기변경)";
    vCtnt += "\r\n\r\n";
    vCtnt += "1. 종목명 : " + txb_ISU_NM.getValue();
    vCtnt += "\r\n\r\n";
    vCtnt += "2. 만기유무 : 변경전 " + txb_ISU_NM.getValue(); + " → 변경후 " + txb_ISU_NM.getValue();
    vCtnt += "\r\n\r\n";
    vCtnt += "3. 만기일 : 변경전 " + scwin.dateForm(edt_CHG_LIST_DD.getValue()) + " → 변경후 " + scwin.dateForm(edt_CHG_LIST_DD.getValue());
    vCtnt += "\r\n\r\n";
    vCtnt += "4. 변경상장일 : " + scwin.dateForm(edt_CHG_LIST_DD.getValue());
    vCtnt += "\r\n\r\n";
    vCtnt += "5. 기타 : 만기 변경에 따른 최종거래일 변경은 추후 관련 공시를 참조하시기 바랍니다.";
    return vCtnt;
};

/**
 * @method
 * @name dateForm
 * @description 년월일 포맷 맞춤 (안내문 작성에서 사용)
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm = function(pStr) {
    let str = "";
    if (pStr === "") {
        str = "없음"; // "★★★★년" + "★★월" + "★★일";

    } else {
        str = pStr.substring(0, 4) + "년 " + pStr.substring(4, 6) + "월 " + pStr.substring(6, 8) + "일";
    }
    return str;
};

/**
 * @method
 * @name parentRefresh
 * @description Parent 화면 Refresh()
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    // Parent 신청내역 화면 Refresh
    let parentWin = $c.frame.path("../");
    parentWin.fn_list_exp_chglist_sync();
};

/**
 * @method
 * @name compDate
 * @description comp Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.compDate = async function() {
    let rslt = true;
    if (txb_EXP_DD.getValue() !== "" && txb_LSTTRD_DD.getValue() !== "") {
        const expDd = txb_EXP_DD.getValue();
        const lsttrdDd = txb_LSTTRD_DD.getValue();
        if (expDd.length === 8 && lsttrdDd.length === 8) {
            if (expDd <= lsttrdDd) {
                await $c.win.alert("최종거래일은 만기일 이전일자로 입력해야합니다.");
                rslt = false;
            }
        }
    }
    return rslt;
};

/**
 * @method
 * @name btn_ExpIsuClose_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ExpIsuClose_onclick = async function() {
    // 닫기(수량변경)
    await $c.win.closePopup();
};

/**
 * @method
 * @name gform_onload
 * @description Form onload event
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // Form onload event
    // PanelToGroupBox(panel_Item);

    let parentWin = $c.frame.path("../");

    // Transaction 구분: 신규(N), 수정(U), 삭제(D)
    scwin.v_SaveKind = parentWin.vIsuChgKind;
    scwin.vIsuCd = parentWin.clickIsuCd; // 종목 코드
    scwin.vDisclsYn = parentWin.clickDisclsYn; // 공시여부

    // 파일 첨부 dataset header

    // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    if (scwin.v_SaveKind === "N") {
        // 신규일 경우
        // 정보조회
        await scwin.selectIsur();
    } else if (scwin.v_SaveKind === "U") {
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vIsuCd = parentWin.clickIsuCd;

        // 상세 정보 조회
        await scwin.selectIsurDetail();
    }

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, scwin.saveExpIsurNew); // 저장
    buttonSet.setUpdateInfo(btn_Update, scwin.saveExpIsurUpdate); // 수정
    buttonSet.setDeleteInfo(btn_Delete, scwin.saveExpIsurDelete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description 저장메세지, 부모화면 Refresh, 화면 닫기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    // 저장메세지, 부모화면 Refresh, 화면 닫기
    $c.lcd.fn_alertMsg('S');
    scwin.parentRefresh();
    if (buttonSet.status === "D") {
        // 삭제처리의 응답인 경우
        await $c.win.closePopup();
    } else {
        await scwin.selectIsurDetail();
    }
};

/**
 * @method
