scwin.cmb_DIGITAL_SECU_EXP_YN_onselchange = function() {
    if (cmb_DIGITAL_SECU_EXP_YN.getValue() === "N") {
        txb_EXP_DD.setValue("");
        txb_EXP_DD.setReadOnly(true);
        img_EXP_DD.setDisabled(true);
        img_EXP_DD.src = "../img/icn_calendar_d.gif";
    } else {
        txb_EXP_DD.setReadOnly(false);
        img_EXP_DD.setDisabled(false);
        img_EXP_DD.src = "../img/icn_calendar.gif";
    }
};

